INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l89',2,12,89,'A Slip of the Tongue','一次口误','复习 KS17/41/65 情态表达(收官包·干净课美语化):must(必须、务必;must have done 对过去的肯定推测)、have to / had to(客观上必须)、needn''t 与 don''t have to(不必)、should / should have done(应该/过去本应做)、mustn''t(禁止)的用法与辨析','“上台一定要沉住气,”老师叮嘱新来的主持人。“你不必做到完美,但要吐字清楚。”那天晚上,主持人要介绍一位著名作家。他太紧张了,一定是把名字说混了。“你不用担心,”作家轻声安慰道,“谁都会这样。”“我当时真该多练练的,”主持人事后说。“别太苛责自己了,”她笑着回答。“下次我一定记得先深呼吸,”他笑道。“你该为自己骄傲——你坚持下来了!”她说。大家都认同:一个小小的口误,不必毁掉一个愉快的夜晚。','{"q":"Listen and answer — What did the teacher tell the new host to do?","options":["Stay calm on stage","Speak very fast","Leave the stage early","Read from a script"],"answer_index":0}'::jsonb,'{"title":"复习 KS17/41/65 情态表达","intro":"本课复习几个常用的情态说法:①must——主观上“必须、务必”(You must stay calm);must have done——对过去的肯定推测“一定……过了”(He must have mixed up the names);②have to / had to——客观上“不得不、必须”,过去用 had to(He had to introduce the writer);③needn''t 和 don''t have to——“不必、无需”(You needn''t worry / You don''t have to be perfect);④should——“应该”,should have done——“过去本应做而没做”(I should have practiced more);⑤mustn''t——“禁止、别”(You mustn''t be so hard on yourself)。","table":{"headers":["表达","例子"],"rows":[["must / must have done","You must stay calm. / He must have mixed up the names."],["have to / had to","He had to introduce a famous writer."],["needn''t / don''t have to","You needn''t worry. / You don''t have to be perfect."],["should / should have done","You should speak clearly. / I should have practiced more."],["mustn''t","You mustn''t be so hard on yourself."]]},"specialRules":[{"rule":"美语“剧院”说 theater(英式 theatre);“电梯”说 elevator(英式 lift)。本课已按美语写。","mark":"theater / elevator"},{"rule":"needn''t / don''t have to = 不必(没必要),mustn''t = 禁止(一定别);must have done 是对过去的推测,should have done 是“本应做却没做”。","mark":"情态辨析"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l89',1,NULL,'"You must stay calm on stage," the teacher told the new host. "You don''t have to be perfect, but you should speak clearly."','“上台一定要沉住气,”老师叮嘱新来的主持人。“你不必做到完美,但要吐字清楚。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l89',2,NULL,'That evening, the host had to introduce a famous writer. He was so nervous that he must have mixed up the names.','那天晚上,主持人要介绍一位著名作家。他太紧张了,一定是把名字说混了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l89',3,NULL,'"You needn''t worry," the writer whispered kindly. "It happens to everyone." "I should have practiced more," the host said afterward.','“你不用担心,”作家轻声安慰道,“谁都会这样。”“我当时真该多练练的,”主持人事后说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l89',4,NULL,'"You mustn''t be so hard on yourself," she replied with a smile. "Next time, I must remember to breathe first," he laughed.','“别太苛责自己了,”她笑着回答。“下次我一定记得先深呼吸,”他笑道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l89',5,NULL,'"You should be proud — you kept going!" she said. Everyone agreed: a small slip needn''t ruin a good evening.','“你该为自己骄傲——你坚持下来了!”她说。大家都认同:一个小小的口误,不必毁掉一个愉快的夜晚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
